{
  "headline": "Focus on high impact filtration and protective masking during {{level.name}} air quality",
  "summary": "Current outdoor air quality is {{level.name}} with US AQI at {{aqi.now}}. Executing these steps reduces household exposure from {{exposure.before}} down to {{exposure.after}}, with the safest outdoor window occurring between {{best.start}} and {{best.end}}.",
  "cards": [
    {
      "actionId": "diy_box_fan_filter",
      "title": "Assemble a DIY box fan filter",
      "why": "Creates effective indoor filtration on a low budget, reducing indoor exposure by {{impact.diy_box_fan_filter.pct}}.",
      "when": "Run continuously in high usage rooms throughout the day.",
      "steps": [
        "Seal a MERV-13 filter tightly against the intake side of a box fan.",
        "Keep the fan running in closed bedrooms for optimal air turnover."
      ]
    },
    {
      "actionId": "n95_for_open_transport",
      "title": "Wear a fitted N95 mask on open transport",
      "why": "Provides crucial respiratory protection against fine particulates, reducing personal intake by {{impact.n95_for_open_transport.pct}}.",
      "when": "Wear whenever walking outside or using open transit during peak hours between {{avoid.start}} and {{avoid.end}}.",
      "steps": [
        "Select a certified N95 or FFP2 respirator.",
        "Check that the nose clip and straps fit snug without gaps."
      ]
    },
    {
      "actionId": "exercise_indoors_when_poor",
      "title": "Move workouts to indoor spaces",
      "why": "Avoids deep inhalation of fine particulate matter, cutting exercise exposure by {{impact.exercise_indoors_when_poor.pct}}.",
      "when": "Whenever pollution sits at {{level.name}} levels.",
      "steps": [
        "Perform bodyweight or indoor cardio routines inside.",
        "Keep room air filtered while exercising."
      ]
    },
    {
      "actionId": "child_play_indoors_when_poor",
      "title": "Keep child play sessions indoors",
      "why": "Protects developing lungs from heavy exertion in high outdoor pollution, lowering exposure by {{impact.child_play_indoors_when_poor.pct}}.",
      "when": "During peak smog hours and throughout {{level.name}} conditions.",
      "steps": [
        "Set up indoor play activities in a room with air filtration.",
        "Avoid sending children to outdoor playgrounds during {{avoid.start}} to {{avoid.end}}."
      ]
    },
    {
      "actionId": "carpool_shared_ride",
      "title": "Share car rides for essential trips",
      "why": "Reduces neighborhood vehicle emissions and saves {{co2e.carpool_shared_ride}} while keeping passengers sheltered.",
      "when": "During regular travel and school drops.",
      "steps": [
        "Coordinate shared rides with neighbors heading on similar routes.",
        "Keep car windows rolled up with air recirculation turned on."
      ]
    }
  ],
  "memberNotes": [
    {
      "group": "child",
      "note": "Children breathe more air per body weight; keep active outdoor games inside during {{level.name}} levels."
    },
    {
      "group": "respiratory",
      "note": "Individuals with respiratory sensitivities should keep preventative medication nearby and rely on N95 protection when traveling."
    },
    {
      "group": "adult",
      "note": "Minimize intense physical exertion outdoors during the highest pollution windows from {{avoid.start}} to {{avoid.end}}."
    }
  ],
  "tradeoffs": [
    "Using open public transit saves emissions but increases particulate intake unless paired with a properly fitted N95 mask."
  ]
}
